import assert from 'node:assert/strict';
import {executeMvp,readMvpView} from '../../lib/mvp/engine.ts';
import {habitableBuildingEntrance} from '../../lib/mvp/habitable-data.ts';
import {getHabitableForestSources} from '../../lib/mvp/habitable-industry.ts';
import type {ItemId,MvpCommand,MvpWorld} from '../../lib/mvp/types.ts';
import type {MvpStore} from '../../lib/mvp/store.ts';

class MemoryStore implements MvpStore {record:{revision:number;world:MvpWorld}|null=null;writes=0;async read(){return structuredClone(this.record);}async insert(world:MvpWorld){assert.equal(this.record,null);this.record={revision:0,world:structuredClone(world)};}async compareAndSwap(revision:number,world:MvpWorld){if(this.record?.revision!==revision)return false;this.record={revision:revision+1,world:structuredClone(world)};this.writes++;return true;}}
// A genuine pre-policy district exercises existing property rights without altering scenery.
const NOW=Date.parse('2026-10-16T03:30:00Z');
type Fixture={store:MemoryStore;owner:string;id:string;at:number};
const world=(s:Fixture)=>s.store.record!.world,p=(s:Fixture)=>world(s).players[s.id],h=(s:Fixture)=>p(s).habitable!,m=(s:Fixture)=>h(s).manager!,b=(s:Fixture,type:string)=>h(s).buildings.find(b=>b.templateId===type)!;
const read=(s:Fixture)=>readMvpView(s.store,s.owner,s.id,s.at),act=(s:Fixture,c:MvpCommand,request=crypto.randomUUID())=>executeMvp(s.store,s.owner,{...c,playerId:s.id},request,undefined,s.at);
async function walk(s:Fixture,point:{x:number;y:number}){await act(s,{type:'habitat.walk',...point});s.at=h(s).movement!.endsAt+1;await read(s);}
async function go(s:Fixture,type:string){await walk(s,habitableBuildingEntrance(h(s),b(s,type))!);}
async function build(s:Fixture,templateId:string,x:number,y:number,rotation=0){await act(s,{type:'habitat.build',templateId,x,y,rotation});s.at=h(s).buildings.at(-1)!.endsAt+1;await read(s);}
async function deposit(s:Fixture,itemId:ItemId,amount:number){let left=amount;for(const lot of structuredClone(p(s).inventory).filter(l=>l.itemId===itemId)){const qty=Math.min(lot.qty,left);if(qty)await act(s,{type:'habitat.storage.deposit',buildingId:b(s,'shed').id,lotId:lot.id,qty});left-=qty;if(!left)break;}assert.equal(left,0);}
async function setup(){const store=new MemoryStore(),owner='industrial-manager-owner',created=await executeMvp(store,owner,{type:'player.create',name:'Alba',stationName:'Industria finita',faction:'cartographers'},crypto.randomUUID(),undefined,NOW),s:Fixture={store,owner,id:created.player!.id,at:NOW};await act(s,{type:'habitat.profile',appearance:'pine',profession:'carpenter'});await build(s,'shed',7,3);await build(s,'workbench',-2,-8,1);await build(s,'planter',8,6);await build(s,'woodlot',-12,1);await act(s,{type:'habitat.residents.initialize'});const carrier=h(s).workforce!.residents.find(r=>r.assignment?.buildingId===b(s,'planter').id)!;await act(s,{type:'habitat.resident.unassign',residentId:carrier.id});s.at=h(s).workforce!.residents.find(r=>r.id===carrier.id)!.relocation!.endsAt+1;await read(s);await act(s,{type:'habitat.resident.assign',residentId:carrier.id,buildingId:b(s,'woodlot').id});s.at=h(s).workforce!.residents.find(r=>r.id===carrier.id)!.relocation!.endsAt+1;await read(s);
  // Eight existing natural timber units fund the extra housing materials. No fixture grant.
  await go(s,'woodlot');await act(s,{type:'habitat.woodlot.start',buildingId:b(s,'woodlot').id,qty:8});const extraction=world(s).jobs[b(s,'woodlot').operation!.jobId];await walk(s,{x:0,y:1.5});s.at=extraction.endsAt+300000;await read(s);await go(s,'shed');for(const lot of structuredClone(b(s,'shed').storage??[]))await act(s,{type:'habitat.storage.withdraw',buildingId:b(s,'shed').id,lotId:lot.id,qty:lot.qty});await walk(s,{x:0,y:1.5});
  await act(s,{type:'habitat.resident.unassign',residentId:carrier.id});s.at=h(s).workforce!.residents.find(r=>r.id===carrier.id)!.relocation!.endsAt+1;await read(s);await act(s,{type:'craft.start',recipeId:'plank',qty:1});await act(s,{type:'craft.start',recipeId:'cloth',qty:1});s.at=Math.max(...Object.values(world(s).jobs).map(j=>j.endsAt))+1;await read(s);await build(s,'sawmill',-12,5);await build(s,'house',-9,9);await go(s,'house');await act(s,{type:'habitat.resident.recruit',houseId:b(s,'house').id});await act(s,{type:'habitat.resident.recruit',houseId:b(s,'house').id});const recruits=h(s).workforce!.residents.filter(r=>r.homeBuildingId===b(s,'house').id);for(const[index,kind]of ['woodlot','sawmill'].entries()){await act(s,{type:'habitat.resident.assign',residentId:recruits[index].id,buildingId:b(s,kind).id});s.at=h(s).workforce!.residents.find(r=>r.id===recruits[index].id)!.relocation!.endsAt+1;await read(s);}await go(s,'shed');await deposit(s,'grain',3);await deposit(s,'water',1);await walk(s,{x:5.4,y:5.9});const sawyer=h(s).workforce!.residents.find(r=>r.assignment?.buildingId===b(s,'sawmill').id)!;await act(s,{type:'habitat.resident.unassign',residentId:sawyer.id});s.at=h(s).workforce!.residents.find(r=>r.id===sawyer.id)!.relocation!.endsAt+1;await read(s);return s;
}
function config(s:Fixture):MvpCommand {const source=getHabitableForestSources(world(s),p(s),s.at)[0]!;assert.ok(source);return{type:'habitat.manager.start',supplyShedId:b(s,'shed').id,workbenchId:b(s,'workbench').id,woodlotId:b(s,'woodlot').id,sawmillId:b(s,'sawmill').id,forestry:{tileId:source.tileId,layerId:source.layerId,maxTimber:4},parallel:true,courierResidentId:h(s).workforce!.residents.find(r=>!r.assignment)!.id,operator:{residentId:h(s).workforce!.residents.find(r=>r.assignment?.buildingId===b(s,'woodlot').id)!.id,allowedJobs:['woodlot','sawmill'],preferredJob:'woodlot'},goals:{ration:1,plank:2,cloth:0},durationMinutes:20,maxOrders:12,inputBudget:80};}
const jobs=(s:Fixture)=>Object.values(world(s).jobs).filter(j=>j.payload.managerPlanId===m(s).id);
const quantity=(s:Fixture,id:ItemId)=>(b(s,'shed').storage??[]).filter(l=>l.itemId===id).reduce((n,l)=>n+l.qty,0);


export {MemoryStore,setup as createOperatorFixture,config as operatorConfig,world as operatorWorld,p as operatorPlayer,h as operatorState,m as operatorManager,b as operatorBuilding,act as operatorAct,read as operatorRead,walk as operatorWalk,go as operatorGo,deposit as operatorDeposit,jobs as operatorJobs,quantity as operatorQuantity};
export type {Fixture as OperatorFixture};
